using Reseau.Utils;

namespace Reseau.AutomateProtocol
{
    // Automate M580 (D16 RU)
    public class FHProtocol : IAutomateProtocol
    {
        public readonly Dictionary<string, Byte[]> dictionnary;

        public FHProtocol(string action) {
            switch(action)
            {
                case "OuvrirAPI":
                    dictionnary = CreateDictionnaryOuvrirAPI();
                    break;
                case "LectureAPI":
                    dictionnary = CreateDictionnaryLectureAPI();
                    break;
                case "EcritureAPI":
                    dictionnary = CreateDictionnaryEcritureAPI();
                    break;
            }
        }

        public Byte[] CalculResponse(string question)
        {
            if (dictionnary.TryGetValue(question, out Byte[] response))
            {
                return response;
            }
            else
            {
                return null;
            }

        }

        public bool IsActionNotImplementend() { 
            return dictionnary == null;
        }

